  var WC_STORM_MOMENTS_STYLE = ".wc-precip-lab {container:storm-lab / inline-size}
.wc-storm-lifecycle {
  --sm-paper:#f4fbfd; --sm-card:#fff; --sm-tint:#e8f2f5; --sm-ink:#173f4c;
  --sm-muted:#3b626f; --sm-line:#6f939f; --sm-focus:#0b6579;
  --sm-activity:#126680; --sm-ground:#276849; --sm-cloud:#d5e6ee; --sm-cloud-line:#153f4c;
  container:storm-lifecycle / inline-size;
}
.dark .wc-storm-lifecycle,.wc-storm-moments.is-dark {
  --sm-paper:#112c37; --sm-card:#173743; --sm-tint:#1d424e; --sm-ink:#f0fbff;
  --sm-muted:#c7dfe8; --sm-line:#668a96; --sm-focus:#7ae4e8;
  --sm-activity:#73cde7; --sm-ground:#a7d5ac; --sm-cloud:#345a6b; --sm-cloud-line:#edfafe;
}
.wc-storm-moments.is-contrast {
  --sm-paper:#fff; --sm-card:#fff; --sm-tint:#fff; --sm-ink:#111;
  --sm-muted:#222; --sm-line:#111; --sm-focus:#005369;
  --sm-activity:#005d79; --sm-ground:#205638; --sm-cloud:#e4e4e4; --sm-cloud-line:#111;
}
.wc-precip-lab .wc-storm-lifecycle {
  padding:16px; border:1px solid var(--sm-line); border-radius:16px;
  background:var(--sm-paper); color:var(--sm-ink); min-width:0;
}
.wc-precip-lab .wc-storm-lifecycle-head {font-size:14px;gap:8px;flex-wrap:wrap;color:var(--sm-ink)}
.wc-precip-lab .wc-storm-lifecycle-head>strong {font-size:16px;line-height:1.4}
.wc-precip-lab #wcStormLifecycleTitle {color:var(--sm-ink)}
.wc-precip-lab .wc-storm-lifecycle-head>span {font-size:13px;color:var(--sm-muted)}
.wc-precip-lab .wc-storm-lifecycle .wc-precip-btn {
  min-height:44px;font-size:14px;line-height:1.4;white-space:normal;
