.wc-sm-question {margin-top:16px;padding-top:4px;border-top:1px solid var(--sm-line)}
.wc-sm-question>summary {display:list-item;list-style:revert;min-height:44px;padding:12px 0;cursor:pointer;font-size:14px;font-weight:750}
.wc-sm-answers {display:grid;gap:8px;margin:12px 0}
.wc-sm-answers button {text-align:left}
.wc-precip-lab .wc-storm-moments button:disabled {opacity:1;cursor:default;color:var(--sm-muted)}
.wc-sm-feedback {padding:12px;border-left:3px solid var(--sm-focus);border-radius:0 10px 10px 0;background:var(--sm-tint)}
.wc-precip-lab .wc-storm-moments .wc-sm-limit {font-size:13px;line-height:1.6;color:var(--sm-muted);margin-top:14px}
.wc-precip-lab .wc-storm-moments a {display:inline-flex;align-items:center;min-height:44px;color:var(--sm-focus);text-decoration:underline;text-underline-offset:3px}
.wc-precip-lab .wc-storm-lifecycle :is(button,input,select,summary,a):focus-visible,
.wc-precip-lab .wc-storm-moments [tabindex='-1']:focus {outline:3px solid var(--sm-focus);outline-offset:3px;border-radius:5px}
@container storm-lab (max-width:820px) {
  .wc-precip-lab .wc-precip-layout {grid-template-columns:minmax(0,1fr)}
  .wc-precip-lab .wc-precip-controls {grid-template-columns:repeat(2,minmax(0,1fr))}
  .wc-precip-lab .wc-precip-control-group:last-child {grid-column:1/-1}
  .wc-precip-lab .wc-precip-head-actions {width:100%}
}
@container storm-lab (max-width:560px) {
  .wc-precip-lab .wc-precip-controls,.wc-precip-lab .wc-precip-metrics,
  .wc-precip-lab .wc-precip-notebook-body,.wc-precip-lab .wc-precip-select-grid {grid-template-columns:minmax(0,1fr)}
  .wc-precip-lab .wc-precip-control-group:last-child {grid-column:auto}
  .wc-precip-lab .wc-precip-canvas {height:290px}
}
@container storm-lifecycle (min-width:620px) {.wc-sm-cards{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container storm-lifecycle (max-width:330px) {
  .wc-precip-lab .wc-storm-stage-segments {grid-template-columns:1fr}
  .wc-precip-lab .wc-storm-playback {grid-template-columns:1fr}
  .wc-sm-stage-button {flex-wrap:wrap}
}
@media(forced-colors:active) {
  .wc-storm-lifecycle,.wc-storm-moments {
    --sm-paper:Canvas!important;--sm-card:Canvas!important;--sm-tint:Canvas!important;
    --sm-ink:CanvasText!important;--sm-muted:CanvasText!important;--sm-line:CanvasText!important;
    --sm-focus:Highlight!important;--sm-activity:Highlight!important;--sm-ground:CanvasText!important;
    --sm-cloud:Canvas!important;--sm-cloud-line:CanvasText!important;forced-color-adjust:none;
  }
  .wc-precip-lab .wc-storm-lifecycle .wc-precip-btn,.wc-precip-lab .wc-storm-moments button,.wc-precip-lab .wc-storm-moments select {background:ButtonFace!important;color:ButtonText!important;border-color:ButtonText!important}
  .wc-precip-lab .wc-storm-lifecycle .wc-precip-btn.is-primary {background:Highlight!important;color:HighlightText!important}
  .wc-sm-scene {background:Canvas;box-shadow:none}
  .wc-sm-card {box-shadow:none}
}
";
